import networkx as nx

edges = [(0,7), (0,4), (0,2), (2,9), (1,4), (4,6), (2,8), (1,8), (3,9)]
G = nx.Graph()
G.add_edges_from(edges)

try:
    cycles = nx.minimum_cycle_basis(G)
    if cycles:
        girth = min(len(c) for c in cycles)
    else:
        girth = float('inf')
    print(f"Girth: {girth}")
except Exception as e:
    print(e)
